const fs=require('fs'),cp=require('child_process'),crypto=require('crypto'),assert=require('assert/strict');
const base="60828812e4f3bbd6e8f2f5ff7d5c3fc096162356",files=["fr/nigeria/ng-vat.html", "fr/tools/ng-impot-societes/index.html", "fr/tools/ng-plus-value/index.html", "fr/tools/ng-retenue-source/index.html", "ha/kayan-aiki/cgt-najeriya/index.html", "ha/kayan-aiki/cit-najeriya/index.html", "ha/kayan-aiki/wht-najeriya/index.html", "nigeria/ng-vat.html", "sw/nigeria/kikokotoo-vat/index.html", "sw/zana/kikokotoo-cgt-nigeria/index.html", "sw/zana/kikokotoo-cit-nigeria/index.html", "sw/zana/kikokotoo-wht-nigeria/index.html", "tools/ng-cgt/index.html", "tools/ng-cit/index.html", "tools/ng-wht/index.html", "yo/awon-ise/cit-naijiria/index.html", "yo/awon-ise/wht-naijiria/index.html"],expectedPairs=[["https://finance.gov.ng/federal-government-issues-transition-guidelines-for-tax-acts-2025/", "https://fmino.gov.ng/federal-government-issues-transition-guidelines-for-tax-acts-2025/"]];
const previous=JSON.parse(cp.execFileSync('git',['show',base+':data/tool-verification.json'],{encoding:'utf8',maxBuffer:8e6})),current=require(process.cwd()+'/data/tool-verification.json');
const pairs=[];function walk(a,b){if(typeof a==='string'&&typeof b==='string'&&a!==b&&a.startsWith('https://')&&b.startsWith('https://'))pairs.push([a,b]);else if(Array.isArray(a)&&Array.isArray(b))a.forEach((v,i)=>walk(v,b[i]));else if(a&&b&&typeof a==='object'&&typeof b==='object')Object.keys(a).filter(k=>k in b).forEach(k=>walk(a[k],b[k]));}walk(previous,current);assert.deepEqual([...new Map(pairs.map(v=>[JSON.stringify(v),v])).values()].sort(),expectedPairs);
const check=process.argv.includes('--check'),rows=[];
for(const file of files){const before=fs.readFileSync(file,'utf8');let after=before;for(const [oldUrl,newUrl]of expectedPairs){assert(before.includes(oldUrl)||before.includes(newUrl),file);after=after.split(oldUrl).join(newUrl);}if(check)assert.equal(after,before,'Generated citation reverted: '+file);else if(after!==before)fs.writeFileSync(file,after);for(const [oldUrl,newUrl]of expectedPairs){assert(!after.includes(oldUrl)&&after.includes(newUrl),file);}rows.push({file,sha256:crypto.createHash('sha256').update(after).digest('hex')});}
if(process.env.RETURN_DIR)fs.writeFileSync(process.env.RETURN_DIR+'/citation-materialization.json',JSON.stringify({source:'current maintained tool-verification URL delta',old_new_pairs:expectedPairs,files:rows,mode:check?'check':'generate'},null,2)+'\n');console.log('Verified17 source-ledger citation pages, check='+check);
